tools.example:
; Refuse to run unless we are in model space
(if (/= (strcase (getvar "CTAB")) "MODEL")
  (progn (princ "\nRun this on the Model tab.") (exit))
)

; Batch plot every layout in the drawing
(vlax-for lay (vla-get-Layouts (vla-get-ActiveDocument (vlax-get-acad-object)))
  (if (/= (strcase (vla-get-Name lay)) "MODEL")
    (setvar "CTAB" (vla-get-Name lay))
  )
)
